I double checked that the concurrent update of pod performed analogously as  in disraption.go fails. I used the following test:
```golang
func TestUpdateAfterPatch(t *testing.T) {
	testCtx := setup(t, "concurrent-updates")
	cs := testCtx.ClientSet
	pod := &v1.Pod{
		ObjectMeta: metav1.ObjectMeta{
			Name: "testpod",
		},
		Spec: v1.PodSpec{
			Containers: []v1.Container{
				{
					Name:  "my",
					Image: "my",
				},
			},
		},
	}
	pod, err := cs.CoreV1().Pods(testCtx.NS.Name).Create(testCtx.Ctx, pod, metav1.CreateOptions{})
	if err != nil {
		t.Fatalf("Error %v, while creating pod: %v", err, klog.KObj(pod))
	}
	newStatus := pod.Status.DeepCopy()
	newStatus.Phase = v1.PodFailed
	if err := util.PatchPodStatus(testCtx.Ctx, cs, pod, newStatus); err != nil {
		t.Fatalf("Error %v, while patching pod (patch1): %v", err, klog.KObj(pod))
	}
	podNew2 := pod.DeepCopy()
	apipod.UpdatePodCondition(&podNew2.Status, &v1.PodCondition{
		Type:   v1.DisruptionTarget,
		Status: v1.ConditionFalse,
	})
	if _, err := cs.CoreV1().Pods(pod.Namespace).UpdateStatus(testCtx.Ctx, podNew2, metav1.UpdateOptions{}); err != nil {
		t.Fatalf("Error %v, while updating pod (update2): %v", err, klog.KObj(pod))
	}
}
```

This fails with ``Error Operation cannot be fulfilled on pods "testpod": the object has been modified; please apply your changes to the latest version and try again, while updating pod (update2): concurrent-updates02bbb0a7-c74f-42ef-a662-373f57ee19b0/testpod`.

So I think the current behavior reflects the sentiment of staying on the safe side expressed also in this [comment](https://github.com/kubernetes/kubernetes/pull/121103#issuecomment-1768951983).
